1	//! [`ForkdBackend`] — the microVM execution tier: a portable REST client of the
2	//! forkd Firecracker controller. Feature-gated behind `microvm`. **Experimental
3	//! skeleton** (SMA-416): the fork→exec→destroy flow is real but the live KVM run
4	//! and egress *enforcement* are deferred to SMA-437; `guarantees().network` is
5	//! honestly `None`.
6	
7	use std::sync::Arc;
8	use std::time::Duration;
9	
10	use async_trait::async_trait;
11	use paigasus_helikon_core::ToolError;
12	
13	use super::{
14	    ExecOutput, ExecRequest, ExecutionBackend, Isolation, SandboxGuarantees, DEFAULT_MAX_OUTPUT,
15	    DEFAULT_TIMEOUT,
16	};
17	
18	const DEFAULT_UA: &str = concat!("paigasus-helikon-tools/", env!("CARGO_PKG_VERSION"));
19	/// Fixed control-plane timeout for the destroy call (the command timeout governs exec).
20	const CONTROL_TIMEOUT: Duration = Duration::from_secs(10);
21	
22	/// Construction-time failures for [`ForkdBackend`]. Runtime failures (daemon
23	/// unreachable, fork/exec error) surface as `ToolError::Other` from `run`.
24	///
25	/// Variants never embed the bearer token — keep auth material out of error text.
26	#[derive(Debug, thiserror::Error)]
27	#[non_exhaustive]
28	pub enum ForkdError {
29	    /// The controller URL could not be parsed.
30	    #[error("invalid forkd controller URL: {0}")]
31	    InvalidUrl(String),
32	    /// A required field (bearer token / snapshot tag) was not set.
33	    #[error("missing required forkd config: {0}")]
34	    MissingConfig(&'static str),
35	    /// The controller CA PEM could not be parsed.
36	    #[error("invalid controller CA certificate")]
37	    InvalidCa,
38	    /// The reqwest client could not be constructed.
39	    #[error("failed to build forkd HTTP client")]
40	    ClientBuild,
41	    /// A plain-`http` controller URL on a non-loopback host — this would send the
42	    /// bearer token in cleartext over the network. Use `https` for remote hosts.
43	    #[error("insecure forkd controller URL: use https for non-loopback hosts")]
44	    InsecureControllerUrl,
45	}
46	
47	/// `POST /v1/sandboxes` request body — fork `n` children (we use 1) copy-on-write
48	/// from a warmed snapshot, each in its own network namespace.
49	#[derive(serde::Serialize)]
50	struct ForkReq<'a> {
51	    snapshot_tag: &'a str,
52	    n: u32,
53	    per_child_netns: bool,
54	}
55	
56	/// One sandbox in the `POST /v1/sandboxes` response **array**. forkd returns more
57	/// fields (snapshot_tag, guest_addr, …); only `id` is needed, the rest are ignored.
58	#[derive(serde::Deserialize)]
59	struct SandboxInfo {
60	    id: String,
61	}
62	
63	/// `POST /v1/sandboxes/{id}/exec` request body. `args` runs verbatim in the guest
64	/// (no shell expansion), so a shell command is wrapped as `["sh","-c","<cmd>"]`.
65	/// `timeout_secs` is the daemon-side cap (we also enforce one client-side).
66	#[derive(serde::Serialize)]
67	struct ExecReq<'a> {
68	    args: [&'a str; 3],
69	    timeout_secs: u64,
70	}
71	
72	/// `POST /v1/sandboxes/{id}/exec` response — captured guest output.
73	#[derive(serde::Deserialize)]
74	struct ExecResp {
75	    #[serde(default)]
76	    stdout: String,
77	    #[serde(default)]
78	    stderr: String,
79	    #[serde(default)]
80	    exit_code: Option<i32>,
81	}
82	
83	/// Domain allow/deny config the backend **carries**. The skeleton does not yet
84	/// *enforce* egress (the netns + CONNECT-proxy layers are SMA-437); this type is
85	/// the seam that follow-up enforces, and the future cloud sibling shares.
86	///
87	/// Matching is sub-domain-aware, case-insensitive, and trailing-dot-insensitive:
88	/// `example.com` matches `example.com` and `api.example.com`.
89	#[derive(Debug, Clone, Default)]
90	pub struct EgressPolicy {
91	    allow: Option<Vec<String>>,
92	    deny: Vec<String>,
93	}
94	
95	impl EgressPolicy {
96	    /// Deny all egress (an empty allow-list permits nothing).
97	    pub fn deny_all() -> Self {
98	        Self {
99	            allow: Some(Vec::new()),
100	            deny: Vec::new(),
101	        }
102	    }
103	
104	    /// Allow all egress (no allow-list and no deny-list).
105	    pub fn allow_all() -> Self {
106	        Self::default()
107	    }
108	
109	    /// Add allowed domains. Setting any allow-list switches the policy to
110	    /// default-deny (only listed domains and their sub-domains are permitted).
111	    pub fn allow_domains<I, S>(mut self, domains: I) -> Self
112	    where
113	        I: IntoIterator<Item = S>,
114	        S: Into<String>,
115	    {
116	        self.allow
117	            .get_or_insert_with(Vec::new)
118	            .extend(domains.into_iter().map(Into::into));
119	        self
120	    }
121	
122	    /// Add denied domains. A deny match always refuses, beating any allow.
123	    pub fn deny_domains<I, S>(mut self, domains: I) -> Self
124	    where
125	        I: IntoIterator<Item = S>,
126	        S: Into<String>,
127	    {
128	        self.deny.extend(domains.into_iter().map(Into::into));
129	        self
130	    }
131	
132	    /// `true` if `host` is permitted: not denied, and — when an allow-list is set
133	    /// — matching it (itself or a sub-domain).
134	    pub fn is_allowed(&self, host: &str) -> bool {
135	        let host = host.trim_end_matches('.').to_ascii_lowercase();
136	        let matches = |entry: &String| {
137	            let e = entry.trim_end_matches('.').to_ascii_lowercase();
138	            host == e || host.ends_with(&format!(".{e}"))
139	        };
140	        if self.deny.iter().any(matches) {
141	            return false;
142	        }
143	        match &self.allow {
144	            Some(list) => list.iter().any(matches),
145	            None => true,
146	        }
147	    }
148	}
