150	/// Builder for [`ForkdBackend`].
151	pub struct ForkdBackendBuilder {
152	    controller_url: String,
153	    bearer_token: Option<String>,
154	    controller_ca: Option<Vec<u8>>,
155	    snapshot: Option<String>,
156	    timeout: Duration,
157	    max_output_bytes: usize,
158	    egress: EgressPolicy,
159	}
160	
161	impl ForkdBackendBuilder {
162	    /// Bearer token presented to the controller (required).
163	    pub fn bearer_token(mut self, token: impl Into<String>) -> Self {
164	        self.bearer_token = Some(token.into());
165	        self
166	    }
167	
168	    /// PEM trust root / cert pin for the controller's TLS (required for a
169	    /// self-signed localhost daemon; use a real CA for a remote host).
170	    pub fn controller_ca(mut self, pem: impl Into<Vec<u8>>) -> Self {
171	        self.controller_ca = Some(pem.into());
172	        self
173	    }
174	
175	    /// Warmed parent snapshot tag to fork children from (required; forkd's
176	    /// `snapshot_tag`).
177	    pub fn snapshot(mut self, tag: impl Into<String>) -> Self {
178	        self.snapshot = Some(tag.into());
179	        self
180	    }
181	
182	    /// Wall-clock timeout for the exec step (default 30s).
183	    pub fn timeout(mut self, timeout: Duration) -> Self {
184	        self.timeout = timeout;
185	        self
186	    }
187	
188	    /// Truncate captured stdout/stderr to this many bytes each (default 1 MiB).
189	    pub fn max_output_bytes(mut self, n: usize) -> Self {
190	        self.max_output_bytes = n;
191	        self
192	    }
193	
194	    /// Egress policy the backend carries (enforcement is SMA-437).
195	    pub fn egress_policy(mut self, policy: EgressPolicy) -> Self {
196	        self.egress = policy;
197	        self
198	    }
199	
200	    /// Build into the concrete [`ForkdBackend`] — used by [`Self::build`] and the
201	    /// in-module unit tests. Public callers go through `build()`.
202	    fn into_backend(self) -> Result<ForkdBackend, ForkdError> {
203	        // Validate the controller URL up front. Reject plain `http` to a
204	        // non-loopback host: the bearer token would travel in cleartext, the
205	        // network-MITM threat the TLS-trust story exists to prevent. Loopback
206	        // `http` (forkd's documented default) stays allowed.
207	        let parsed = reqwest::Url::parse(&self.controller_url)
208	            .map_err(|_| ForkdError::InvalidUrl(self.controller_url.clone()))?;
209	        if parsed.scheme() == "http" && !host_is_loopback(&parsed) {
210	            return Err(ForkdError::InsecureControllerUrl);
211	        }
212	        let token = self
213	            .bearer_token
214	            .ok_or(ForkdError::MissingConfig("bearer_token"))?;
215	        let snapshot = self.snapshot.ok_or(ForkdError::MissingConfig("snapshot"))?;
216	        let mut cb = reqwest::Client::builder()
217	            .user_agent(DEFAULT_UA)
218	            .connect_timeout(CONTROL_TIMEOUT);
219	        if let Some(pem) = &self.controller_ca {
220	            let cert = reqwest::Certificate::from_pem(pem).map_err(|_| ForkdError::InvalidCa)?;
221	            cb = cb.add_root_certificate(cert);
222	        }
223	        let client = cb.build().map_err(|_| ForkdError::ClientBuild)?;
224	        Ok(ForkdBackend {
225	            client,
226	            base: self.controller_url.trim_end_matches('/').to_string(),
227	            token,
228	            snapshot,
229	            timeout: self.timeout,
230	            max_output_bytes: self.max_output_bytes,
231	            egress: self.egress,
232	        })
233	    }
234	
235	    /// Finish building into a shareable `Arc<dyn ExecutionBackend>`.
236	    pub fn build(self) -> Result<Arc<dyn ExecutionBackend>, ForkdError> {
237	        Ok(Arc::new(self.into_backend()?))
238	    }
239	}
