241	/// The microVM execution backend — a REST client of the forkd controller. See
242	/// the module docs: experimental skeleton; egress is carried but not enforced.
243	///
244	/// `Debug` is implemented manually to **redact the bearer `token`** — a derived
245	/// `Debug` would leak it into logs/traces.
246	pub struct ForkdBackend {
247	    client: reqwest::Client,
248	    base: String,
249	    token: String,
250	    snapshot: String,
251	    timeout: Duration,
252	    max_output_bytes: usize,
253	    egress: EgressPolicy,
254	}
255	
256	impl std::fmt::Debug for ForkdBackend {
257	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
258	        f.debug_struct("ForkdBackend")
259	            .field("base", &self.base)
260	            .field("token", &"<redacted>")
261	            .field("snapshot", &self.snapshot)
262	            .field("timeout", &self.timeout)
263	            .field("max_output_bytes", &self.max_output_bytes)
264	            .field("egress", &self.egress)
265	            .finish_non_exhaustive()
266	    }
267	}
268	
269	impl ForkdBackend {
270	    /// Start building a backend against the controller at `controller_url`
271	    /// (e.g. `"https://127.0.0.1:8889"`). Defaults: 30s timeout, 1 MiB output
272	    /// cap, `EgressPolicy::deny_all()`.
273	    pub fn builder(controller_url: impl Into<String>) -> ForkdBackendBuilder {
274	        ForkdBackendBuilder {
275	            controller_url: controller_url.into(),
276	            bearer_token: None,
277	            controller_ca: None,
278	            snapshot: None,
279	            timeout: DEFAULT_TIMEOUT,
280	            max_output_bytes: DEFAULT_MAX_OUTPUT,
281	            egress: EgressPolicy::deny_all(),
282	        }
283	    }
284	
285	    /// The egress policy this backend carries. Enforcement is deferred to
286	    /// SMA-437; this read accessor lets callers inspect the declared intent.
287	    pub fn egress_policy(&self) -> &EgressPolicy {
288	        &self.egress
289	    }
290	
291	    async fn post_json<T: serde::de::DeserializeOwned>(
292	        &self,
293	        url: &str,
294	        body: &impl serde::Serialize,
295	    ) -> Result<T, ToolError> {
296	        // The bearer token rides only in the Authorization header — never in
297	        // the URL/body — so reqwest's error Display (URL only) cannot leak it.
298	        let resp = self
299	            .client
300	            .post(url)
301	            .bearer_auth(&self.token)
302	            .json(body)
303	            .send()
304	            .await
305	            .map_err(|e| ToolError::Other(anyhow::anyhow!("forkd request failed: {e}")))?;
306	        if !resp.status().is_success() {
307	            return Err(ToolError::Other(anyhow::anyhow!(
308	                "forkd controller returned HTTP {}",
309	                resp.status().as_u16()
310	            )));
311	        }
312	        resp.json::<T>()
313	            .await
314	            .map_err(|e| ToolError::Other(anyhow::anyhow!("forkd response decode failed: {e}")))
315	    }
316	
317	    async fn fork(&self) -> Result<String, ToolError> {
318	        let url = format!("{}/v1/sandboxes", self.base);
319	        let body = ForkReq {
320	            snapshot_tag: &self.snapshot,
321	            n: 1,
322	            per_child_netns: true,
323	        };
324	        // Fork returns an array (n children); we requested 1, so take the first.
325	        let list: Vec<SandboxInfo> =
326	            tokio::time::timeout(self.timeout, self.post_json(&url, &body))
327	                .await
328	                .map_err(|_| ToolError::Other(anyhow::anyhow!("forkd: fork timed out")))??;
329	        list.into_iter()
330	            .next()
331	            .map(|s| s.id)
332	            .ok_or_else(|| ToolError::Other(anyhow::anyhow!("forkd returned no sandbox")))
333	    }
334	
335	    async fn exec(&self, id: &str, command: &str) -> Result<ExecResp, ToolError> {
336	        let url = format!("{}/v1/sandboxes/{id}/exec", self.base);
337	        // `args` runs verbatim in the guest, so wrap the shell command.
338	        self.post_json(
339	            &url,
340	            &ExecReq {
341	                args: ["sh", "-c", command],
342	                timeout_secs: self.timeout.as_secs(),
343	            },
344	        )
345	        .await
346	    }
347	
348	    async fn destroy(&self, id: &str) {
349	        // Best-effort teardown; failures here are not surfaced to the model.
350	        let url = format!("{}/v1/sandboxes/{id}", self.base);
351	        let _ = self
352	            .client
353	            .delete(&url)
354	            .bearer_auth(&self.token)
355	            .send()
356	            .await;
357	    }
358	}
359	
360	/// `true` if `url`'s host is loopback (`localhost`, `127.0.0.0/8`, or `::1`), so a
361	/// plain-`http` controller there does not expose the bearer token to the network.
362	fn host_is_loopback(url: &reqwest::Url) -> bool {
363	    let Some(host) = url.host_str() else {
364	        return false;
365	    };
366	    // `host_str` may keep IPv6 brackets (`[::1]`); strip them before comparing.
367	    let host = host.trim_start_matches('[').trim_end_matches(']');
368	    host.eq_ignore_ascii_case("localhost")
369	        || host == "::1"
370	        || host
371	            .parse::<std::net::Ipv4Addr>()
372	            .is_ok_and(|ip| ip.is_loopback())
373	}
374	
375	/// Truncate `s` to `cap` bytes on a char boundary; returns `(s, truncated)`.
376	fn truncate(mut s: String, cap: usize) -> (String, bool) {
377	    if s.len() <= cap {
378	        return (s, false);
379	    }
380	    let mut end = cap;
381	    while end > 0 && !s.is_char_boundary(end) {
382	        end -= 1;
383	    }
384	    s.truncate(end);
385	    (s, true)
386	}
