388	#[async_trait]
389	impl ExecutionBackend for ForkdBackend {
390	    async fn run(&self, req: ExecRequest) -> Result<ExecOutput, ToolError> {
391	        // Accepted skeleton gap: if the controller commits a fork but we fail to
392	        // read its id (decode error / client timeout after commit), that sandbox
393	        // is orphaned — we have no id to DELETE. SMA-437 adds GC/reconciliation.
394	        let id = self.fork().await?;
395	        // The wall-clock command timeout governs exec; teardown always runs.
396	        let exec_result = tokio::time::timeout(self.timeout, self.exec(&id, &req.command)).await;
397	        let _ = tokio::time::timeout(CONTROL_TIMEOUT, self.destroy(&id)).await;
398	        match exec_result {
399	            Ok(Ok(resp)) => {
400	                let (stdout, t1) = truncate(resp.stdout, self.max_output_bytes);
401	                let (stderr, t2) = truncate(resp.stderr, self.max_output_bytes);
402	                Ok(ExecOutput::new(
403	                    stdout,
404	                    stderr,
405	                    resp.exit_code,
406	                    false,
407	                    t1 || t2,
408	                ))
409	            }
410	            Ok(Err(e)) => Err(e),
411	            Err(_) => Ok(ExecOutput::new(
412	                String::new(),
413	                String::new(),
414	                None,
415	                true,
416	                false,
417	            )),
418	        }
419	    }
420	
421	    fn guarantees(&self) -> SandboxGuarantees {
422	        SandboxGuarantees::new(
423	            Isolation::Virtualized, // filesystem — separate guest kernel + rootfs
424	            Isolation::None,        // network — egress NOT filtered yet (SMA-437)
425	            Isolation::Virtualized, // syscalls — guest kernel, not a host filter
426	            "forkd (firecracker microvm — experimental)",
427	        )
428	    }
429	}
