432	mod tests {
433	    use super::*;
434	
435	    #[test]
436	    fn fork_and_exec_responses_deserialize() {
437	        // Fork returns an ARRAY of sandboxes (even for n:1); we take the first.
438	        // Unknown fields (snapshot_tag, …) are ignored.
439	        let v: Vec<SandboxInfo> =
440	            serde_json::from_str(r#"[{"id":"sb-9","snapshot_tag":"t"}]"#).unwrap();
441	        assert_eq!(v[0].id, "sb-9");
442	        // exit_code may be absent (killed by signal) -> None.
443	        let e: ExecResp =
444	            serde_json::from_str(r#"{"stdout":"hi","stderr":"","exit_code":0}"#).unwrap();
445	        assert_eq!(e.stdout, "hi");
446	        assert_eq!(e.exit_code, Some(0));
447	        let e2: ExecResp = serde_json::from_str(r#"{}"#).unwrap();
448	        assert_eq!(e2.stdout, "");
449	        assert_eq!(e2.exit_code, None);
450	    }
451	
452	    #[test]
453	    fn requests_serialize_to_forkd_shapes() {
454	        // Pins the wire shape and exercises the request structs.
455	        let f = serde_json::to_value(ForkReq {
456	            snapshot_tag: "t",
457	            n: 1,
458	            per_child_netns: true,
459	        })
460	        .unwrap();
461	        assert_eq!(f["snapshot_tag"], "t");
462	        assert_eq!(f["n"], 1);
463	        assert_eq!(f["per_child_netns"], true);
464	        let e = serde_json::to_value(ExecReq {
465	            args: ["sh", "-c", "echo hi"],
466	            timeout_secs: 30,
467	        })
468	        .unwrap();
469	        assert_eq!(e["args"][0], "sh");
470	        assert_eq!(e["args"][2], "echo hi");
471	        assert_eq!(e["timeout_secs"], 30);
472	    }
473	
474	    #[test]
475	    fn forkd_error_never_embeds_a_token() {
476	        // Construction errors must be safe to log: no auth material in Display.
477	        let e = ForkdError::MissingConfig("bearer_token");
478	        let s = e.to_string();
479	        assert!(s.contains("bearer_token"));
480	        assert!(!s.to_lowercase().contains("secret"));
481	    }
482	
483	    #[test]
484	    fn egress_policy_deny_all_then_allowlist() {
485	        let p = EgressPolicy::deny_all().allow_domains(["pypi.org"]);
486	        assert!(p.is_allowed("pypi.org"));
487	        assert!(p.is_allowed("files.pypi.org")); // sub-domain
488	        assert!(!p.is_allowed("evil.test")); // not on the allow-list
489	    }
490	
491	    #[test]
492	    fn egress_policy_deny_beats_allow_and_default_allows() {
493	        let p = EgressPolicy::allow_all().deny_domains(["evil.test"]);
494	        assert!(!p.is_allowed("evil.test"));
495	        assert!(!p.is_allowed("api.evil.test")); // sub-domain
496	        assert!(p.is_allowed("good.test")); // no allow-list -> default allow
497	    }
498	
499	    #[test]
500	    fn guarantees_are_honest() {
501	        let b = ForkdBackend::builder("https://localhost:8080")
502	            .bearer_token("t")
503	            .snapshot("s")
504	            .into_backend()
505	            .unwrap();
506	        let g = b.guarantees();
507	        assert_eq!(g.filesystem, Isolation::Virtualized);
508	        assert_eq!(g.syscalls, Isolation::Virtualized);
509	        assert_eq!(g.network, Isolation::None); // egress NOT enforced in the skeleton
510	        assert!(g.label.contains("experimental"));
511	    }
512	
513	    #[test]
514	    fn builder_carries_egress_policy_and_requires_fields() {
515	        // Missing snapshot -> construction error.
516	        let err = ForkdBackend::builder("https://localhost:8080")
517	            .bearer_token("t")
518	            .into_backend()
519	            .unwrap_err();
520	        assert!(matches!(err, ForkdError::MissingConfig("snapshot")));
521	        // The configured policy is carried on the backend.
522	        let b = ForkdBackend::builder("https://localhost:8080")
523	            .bearer_token("t")
524	            .snapshot("s")
525	            .egress_policy(EgressPolicy::deny_all().allow_domains(["pypi.org"]))
526	            .into_backend()
527	            .unwrap();
528	        assert!(b.egress_policy().is_allowed("pypi.org"));
529	        assert!(!b.egress_policy().is_allowed("evil.test"));
530	    }
531	
532	    #[test]
533	    fn rejects_insecure_remote_http_controller() {
534	        // Remote plain-HTTP would leak the bearer token in cleartext — rejected.
535	        let err = ForkdBackend::builder("http://forkd.example.com:8889")
536	            .bearer_token("t")
537	            .snapshot("s")
538	            .into_backend()
539	            .unwrap_err();
540	        assert!(matches!(err, ForkdError::InsecureControllerUrl));
541	        // Loopback plain-HTTP (forkd's documented default) is allowed.
542	        assert!(ForkdBackend::builder("http://127.0.0.1:8889")
543	            .bearer_token("t")
544	            .snapshot("s")
545	            .into_backend()
546	            .is_ok());
547	        // HTTPS to a remote host is allowed.
548	        assert!(ForkdBackend::builder("https://forkd.example.com:8889")
549	            .bearer_token("t")
550	            .snapshot("s")
551	            .into_backend()
552	            .is_ok());
553	    }
554	
555	    #[test]
556	    fn debug_redacts_the_bearer_token() {
557	        let b = ForkdBackend::builder("https://localhost:8080")
558	            .bearer_token("super-secret-token")
559	            .snapshot("s")
560	            .into_backend()
561	            .unwrap();
562	        let dbg = format!("{b:?}");
563	        assert!(
564	            !dbg.contains("super-secret-token"),
565	            "token leaked in Debug: {dbg}"
566	        );
567	        assert!(dbg.contains("redacted"));
568	    }
569	}
