43	/// A backend that runs one shell command under some containment tier.
44	///
45	/// Object-safe and not generic over the agent context, so one value is shared as
46	/// `Arc<dyn ExecutionBackend>` across agents of any context type. Swapping the
47	/// backend needs no change to [`crate::BashTool`] or agent code.
48	#[async_trait]
49	pub trait ExecutionBackend: Send + Sync {
50	    /// Run `req.command` to completion under this backend's containment.
51	    async fn run(&self, req: ExecRequest) -> Result<ExecOutput, ToolError>;
52	
53	    /// What this backend actually enforces — surfaced in docs, the model-facing
54	    /// tool description, and traces. Describes *containment*, not approval.
55	    fn guarantees(&self) -> SandboxGuarantees;
56	}
