58	/// A request to run one shell command. `#[non_exhaustive]` so per-call knobs
59	/// (stdin, env overrides) can be added later without a breaking change.
60	#[derive(Debug, Clone)]
61	#[non_exhaustive]
62	pub struct ExecRequest {
63	    /// The shell command (`sh -c <command>` on unix, `cmd /C` on Windows).
64	    pub command: String,
65	}
66	
67	impl ExecRequest {
68	    /// Build a request from a command string.
69	    pub fn new(command: impl Into<String>) -> Self {
70	        Self {
71	            command: command.into(),
72	        }
73	    }
74	}
