112	/// The isolation level enforced on one axis (filesystem / network / syscalls).
113	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
114	#[non_exhaustive]
115	pub enum Isolation {
116	    /// No OS enforcement — the command has the same access this process does.
117	    None,
118	    /// Enforced by an OS kernel mechanism (Landlock / seccomp-bpf).
119	    OsKernel,
120	    /// Isolated by a hardware-virtualization (KVM/hypervisor) boundary — a
121	    /// separate guest kernel. `Virtualized` means the whole machine is isolated,
122	    /// **not** that any one axis is filtered: a microVM does not filter syscalls
123	    /// the way `OsKernel` (seccomp) does — the guest issues syscalls to its own
124	    /// kernel. Stronger overall than `OsKernel`, but read each axis as "behind a
125	    /// VM boundary," not "restricted by an allowlist."
126	    Virtualized,
127	}
