160	/// Resource limits applied to a command via `setrlimit` (unix). Each `None`
161	/// leaves the inherited limit. See `HostBackend` for the default policy.
162	///
163	/// Not `#[non_exhaustive]`: this is user-built config (struct-literal
164	/// construction from consumer code and integration tests); adding a field later
165	/// is an accepted 0.x breaking change.
166	#[derive(Debug, Clone, Default)]
167	pub struct ResourceLimits {
168	    /// `RLIMIT_CPU` — CPU seconds.
169	    pub cpu_seconds: Option<u64>,
170	    /// `RLIMIT_FSIZE` — max bytes a single file write may reach.
171	    pub file_size_bytes: Option<u64>,
172	    /// `RLIMIT_AS` — virtual address-space cap. Approximate; off by default
173	    /// because it spuriously kills threaded/`mmap`-heavy programs.
174	    pub address_space_bytes: Option<u64>,
175	}
