177	/// Internal config every backend shares; consumed by [`spawn_capped`].
178	pub(crate) struct ExecConfig {
179	    pub(crate) cwd: PathBuf,
180	    pub(crate) env_allowlist: Vec<String>,
181	    pub(crate) timeout: Duration,
182	    pub(crate) max_output_bytes: usize,
