185	use std::process::Stdio;
186	use tokio::io::AsyncReadExt;
187	
188	/// Grace period for reaping a killed process and draining its pipes.
189	const GRACE: Duration = Duration::from_secs(5);
190	
191	/// Spawn `command` under `cfg`, draining stdout/stderr concurrently, killing the
192	/// whole process group on timeout. `prefix`, when non-empty, is prepended as
193	/// `program [args...]` ahead of `sh -c <command>` (used by the macOS Seatbelt
194	/// backend to wrap the shell in `sandbox-exec`). `configure_child` runs in the
195	/// **parent** to install backend-specific `pre_exec` hooks before spawn.
196	pub(crate) async fn spawn_capped(
197	    cfg: &ExecConfig,
198	    prefix: &[OsString],
199	    command: &str,
200	    configure_child: impl FnOnce(&mut tokio::process::Command),
201	) -> Result<ExecOutput, ToolError> {
202	    let mut cmd = build_command(prefix, command);
203	    cmd.current_dir(&cfg.cwd)
204	        .env_clear()
205	        .stdin(Stdio::null())
206	        .stdout(Stdio::piped())
207	        .stderr(Stdio::piped());
208	    for name in &cfg.env_allowlist {
209	        if let Ok(val) = std::env::var(name) {
210	            cmd.env(name, val);
211	        }
212	    }
213	    #[cfg(unix)]
214	    {
215	        // New process group so a timeout can kill the whole subtree.
216	        cmd.process_group(0);
217	    }
218	    configure_child(&mut cmd);
219	
220	    let mut child = cmd
221	        .spawn()
222	        .map_err(|e| ToolError::Other(anyhow::anyhow!("failed to spawn shell: {e}")))?;
223	
224	    #[cfg(unix)]
225	    let pgid = child.id();
226	
227	    let stdout_pipe = child.stdout.take().expect("piped stdout");
228	    let stderr_pipe = child.stderr.take().expect("piped stderr");
229	
230	    let cap = cfg.max_output_bytes;
231	    let out_handle = tokio::spawn(read_capped(stdout_pipe, cap));
232	    let err_handle = tokio::spawn(read_capped(stderr_pipe, cap));
233	
234	    let mut timed_out = false;
235	    let exit_code: Option<i32>;
236	    match tokio::time::timeout(cfg.timeout, child.wait()).await {
237	        Ok(status) => {
238	            exit_code = status.map_err(|e| ToolError::Other(e.into()))?.code();
239	        }
240	        Err(_) => {
241	            timed_out = true;
242	            #[cfg(unix)]
243	            {
244	                if let Some(pid) = pgid {
245	                    // SAFETY: pid < 4_194_304 on supported platforms, so the cast
246	                    // and negation are valid; ESRCH (group already gone) is benign.
247	                    let _ = unsafe { libc::kill(-(pid as i32), libc::SIGKILL) };
248	                }
249	            }
250	            #[cfg(not(unix))]
251	            {
252	                let _ = child.start_kill();
253	            }
254	            exit_code = match tokio::time::timeout(GRACE, child.wait()).await {
255	                Ok(Ok(status)) => status.code(),
256	                _ => None,
257	            };
258	        }
259	    }
260	
261	    let ((stdout, out_trunc), (stderr, err_trunc)) =
262	        tokio::join!(join_reader(out_handle), join_reader(err_handle));
263	
264	    Ok(ExecOutput {
265	        stdout,
266	        stderr,
267	        exit_code,
268	        timed_out,
269	        truncated: out_trunc || err_trunc,
270	    })
271	}
