273	/// Build the platform shell command without yet setting cwd/env. `prefix`, when
274	/// non-empty, is prepended as `program [args...]` before `sh -c <command>` — used
275	/// by the macOS Seatbelt backend to wrap the shell in `sandbox-exec`. Empty for
276	/// the host and Linux backends.
277	fn build_command(prefix: &[OsString], command: &str) -> tokio::process::Command {
278	    #[cfg(unix)]
279	    {
280	        match prefix.split_first() {
281	            Some((program, rest)) => {
282	                let mut c = tokio::process::Command::new(program);
283	                c.args(rest).arg("sh").arg("-c").arg(command);
284	                c
285	            }
286	            None => {
287	                let mut c = tokio::process::Command::new("sh");
288	                c.arg("-c").arg(command);
289	                c
290	            }
291	        }
292	    }
293	    #[cfg(windows)]
294	    {
295	        // `prefix` is always empty on Windows; bind it to avoid `unused_variables`
296	        // under `-D warnings` (clippy runs on ubuntu; Windows is signal-only).
297	        let _ = prefix;
298	        let mut c = tokio::process::Command::new("cmd");
299	        c.arg("/C").arg(command);
300	        c
301	    }
302	}
303	
304	async fn join_reader(handle: tokio::task::JoinHandle<(String, bool)>) -> (String, bool) {
305	    let abort = handle.abort_handle();
306	    match tokio::time::timeout(GRACE, handle).await {
307	        Ok(Ok(captured)) => captured,
308	        _ => {
309	            abort.abort();
310	            (String::new(), false)
311	        }
312	    }
313	}
314	
315	async fn read_capped<R>(pipe: R, cap: usize) -> (String, bool)
316	where
317	    R: tokio::io::AsyncRead + Unpin + Send + 'static,
318	{
319	    let mut buf = Vec::new();
320	    let _ = pipe.take((cap as u64) + 1).read_to_end(&mut buf).await;
321	    let truncated = buf.len() > cap;
322	    buf.truncate(cap);
323	    (String::from_utf8_lossy(&buf).into_owned(), truncated)
324	}
325	
326	/// Apply `limits` to the current process via `setrlimit`. Async-signal-safe
327	/// (only `setrlimit` syscalls, no allocation) so it is callable from `pre_exec`.
328	#[cfg(unix)]
329	pub(crate) fn apply_rlimits(limits: &ResourceLimits) -> std::io::Result<()> {
330	    // SAFETY: setrlimit with a stack-allocated rlimit is async-signal-safe.
331	    unsafe {
332	        // The resource arg's type differs per target (`c_int` on macOS/BSD/musl,
333	        // `__rlimit_resource_t` on Linux glibc), so it is inferred from the
334	        // platform's `RLIMIT_*` constants rather than fixed to one type.
335	        let set = |res, val: u64| -> std::io::Result<()> {
336	            let rl = libc::rlimit {
337	                rlim_cur: val as libc::rlim_t,
338	                rlim_max: val as libc::rlim_t,
339	            };
340	            if libc::setrlimit(res, &rl) != 0 {
341	                return Err(std::io::Error::last_os_error());
342	            }
343	            Ok(())
344	        };
345	        if let Some(s) = limits.cpu_seconds {
346	            set(libc::RLIMIT_CPU, s)?;
347	        }
348	        if let Some(b) = limits.file_size_bytes {
349	            set(libc::RLIMIT_FSIZE, b)?;
350	        }
351	        if let Some(b) = limits.address_space_bytes {
352	            set(libc::RLIMIT_AS, b)?;
353	        }
354	    }
355	    Ok(())
356	}
