FROM ubuntu:22.04
ARG FORKD_VERSION=0.5.2
RUN apt-get update && apt-get install -y --no-install-recommends \
    ca-certificates curl iproute2 iptables busybox-static && rm -rf /var/lib/apt/lists/*
