21	/// Per-connection I/O timeout: header read and DNS lookup must complete within this.
22	const IO_TIMEOUT: Duration = Duration::from_secs(5);
23	
24	/// An egress-policy-enforcing forward proxy. Run it with [`Self::serve`] against a
25	/// bound [`TcpListener`]; each accepted connection is handled on its own task.
26	///
27	/// The proxy is the application-layer half of the layered egress model (SMA-437):
28	/// it filters HTTP/S by domain. The L3/L4 default-deny that forces guest traffic
29	/// through it is the deployment's per-VM netns config (see the runbook).
30	pub struct EgressProxy {
31	    policy: Arc<EgressPolicy>,
32	}
33	
34	impl EgressProxy {
35	    /// Build a proxy enforcing `policy`.
36	    pub fn new(policy: EgressPolicy) -> Self {
37	        Self {
38	            policy: Arc::new(policy),
39	        }
40	    }
41	
42	    /// Accept connections on `listener` until it errors, handling each on a task.
43	    pub async fn serve(self, listener: TcpListener) -> io::Result<()> {
44	        loop {
45	            let (sock, _peer) = listener.accept().await?;
46	            let policy = Arc::clone(&self.policy);
47	            tokio::spawn(async move {
48	                let _ = handle(sock, policy).await;
49	            });
50	        }
51	    }
52	}
