54	const DENY: &[u8] = b"HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\n\r\n";
55	const OK: &[u8] = b"HTTP/1.1 200 Connection Established\r\n\r\n";
56	const BAD: &[u8] = b"HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n";
57	const MAX_HEAD: usize = 16 * 1024;
