59	async fn handle(mut client: TcpStream, policy: Arc<EgressPolicy>) -> io::Result<()> {
60	    // Read the request head (request line + headers) up to CRLFCRLF, bounded.
61	    let mut head = Vec::with_capacity(1024);
62	    let mut byte = [0u8; 1];
63	    while !head.windows(4).any(|w| w == b"\r\n\r\n") {
64	        if head.len() >= MAX_HEAD {
65	            client.write_all(BAD).await?;
66	            return Ok(());
67	        }
68	        let n = match tokio::time::timeout(IO_TIMEOUT, client.read(&mut byte)).await {
69	            Ok(Ok(n)) => n,
70	            Ok(Err(e)) => return Err(e),
71	            Err(_) => {
72	                // Header read timed out.
73	                let _ = client.write_all(BAD).await;
74	                return Ok(());
75	            }
76	        };
77	        if n == 0 {
