79	        }
80	        head.push(byte[0]);
81	    }
82	    let text = String::from_utf8_lossy(&head);
83	    let Some(request_line) = text.lines().next() else {
84	        client.write_all(BAD).await?;
85	        return Ok(());
86	    };
87	    let mut parts = request_line.split_whitespace();
88	    let method = parts.next().unwrap_or("");
89	    let target = parts.next().unwrap_or("");
