// Standalone build of the SMA-437 EgressProxy for live GCP validation.
// policy fns + EgressPolicy are copied verbatim from
// crates/paigasus-helikon-tools/src/net/policy.rs; the proxy is copied verbatim
// from src/net/proxy.rs (the enforced path uses only tokio + EgressPolicy, no
// reqwest/url/core), so this binary exercises the SAME logic the CI tests cover.

use std::io;
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr, SocketAddr};
use std::sync::Arc;
use std::time::Duration;

use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};

// ============== policy.rs (verbatim logic) ==============

pub fn host_allowed(host: &str, allow: Option<&[String]>, deny: &[String]) -> bool {
    let host = host.trim_end_matches('.').to_ascii_lowercase();
    let matches = |entry: &String| {
        let e = entry.trim_end_matches('.').to_ascii_lowercase();
        host == e || host.ends_with(&format!(".{e}"))
    };
    if deny.iter().any(matches) {
        return false;
    }
    match allow {
        Some(list) => list.iter().any(matches),
        None => true,
    }
}

pub fn ip_blocked(ip: IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => v4_blocked(v4),
        IpAddr::V6(v6) => {
            if v6.is_loopback()
                || v6.is_unspecified()
                || v6.is_multicast()
                || is_ula(v6)
                || is_v6_link_local(v6)
                || is_v6_documentation(v6)
            {
                return true;
            }
            if let Some(v4) = v6.to_ipv4_mapped().or_else(|| v6.to_ipv4()) {
                return v4_blocked(v4);
            }
            false
        }
    }
}

fn v4_blocked(ip: Ipv4Addr) -> bool {
    ip.is_loopback()
        || ip.is_private()
        || ip.is_link_local()
        || ip.is_unspecified()
        || ip.is_broadcast()
        || ip.is_documentation()
        || ip.is_multicast()
        || is_cgnat(ip)
        || is_benchmarking_v4(ip)
        || is_reserved_future_v4(ip)
}

fn is_cgnat(ip: Ipv4Addr) -> bool {
    let o = ip.octets();
    o[0] == 100 && (64..=127).contains(&o[1])
}
fn is_benchmarking_v4(ip: Ipv4Addr) -> bool {
    let o = ip.octets();
    o[0] == 198 && (18..=19).contains(&o[1])
}
fn is_reserved_future_v4(ip: Ipv4Addr) -> bool {
    ip.octets()[0] >= 240
}
fn is_v6_documentation(ip: Ipv6Addr) -> bool {
    let s = ip.segments();
    s[0] == 0x2001 && s[1] == 0x0db8
}
fn is_ula(ip: Ipv6Addr) -> bool {
    (ip.segments()[0] & 0xfe00) == 0xfc00
}
fn is_v6_link_local(ip: Ipv6Addr) -> bool {
    (ip.segments()[0] & 0xffc0) == 0xfe80
}

#[derive(Clone, Default)]
pub struct EgressPolicy {
    allow: Option<Vec<String>>,
    deny: Vec<String>,
    allow_private_ips: bool,
}

impl EgressPolicy {
    pub fn deny_all() -> Self {
        Self {
            allow: Some(Vec::new()),
            deny: Vec::new(),
            allow_private_ips: false,
        }
    }
    pub fn allow_domains<I, S>(mut self, domains: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        self.allow
            .get_or_insert_with(Vec::new)
            .extend(domains.into_iter().map(Into::into));
        self
    }
    #[allow(dead_code)]
    pub fn deny_domains<I, S>(mut self, domains: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        self.deny.extend(domains.into_iter().map(Into::into));
        self
    }
    pub fn allow_private_ips(mut self, allow: bool) -> Self {
        self.allow_private_ips = allow;
        self
    }
    pub fn is_host_allowed(&self, host: &str) -> bool {
        host_allowed(host, self.allow.as_deref(), &self.deny)
    }
    pub fn is_ip_allowed(&self, ip: IpAddr) -> bool {
        self.allow_private_ips || !ip_blocked(ip)
    }
}

// ============== proxy.rs (verbatim) ==============

const IO_TIMEOUT: Duration = Duration::from_secs(5);

pub struct EgressProxy {
    policy: Arc<EgressPolicy>,
}

impl EgressProxy {
    pub fn new(policy: EgressPolicy) -> Self {
        Self {
            policy: Arc::new(policy),
        }
    }
    pub async fn serve(self, listener: TcpListener) -> io::Result<()> {
        loop {
            let (sock, _peer) = listener.accept().await?;
            let policy = Arc::clone(&self.policy);
            tokio::spawn(async move {
                let _ = handle(sock, policy).await;
            });
        }
    }
}

const DENY: &[u8] = b"HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\n\r\n";
const OK: &[u8] = b"HTTP/1.1 200 Connection Established\r\n\r\n";
const BAD: &[u8] = b"HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n";
const MAX_HEAD: usize = 16 * 1024;

async fn handle(mut client: TcpStream, policy: Arc<EgressPolicy>) -> io::Result<()> {
    let mut head = Vec::with_capacity(1024);
    let mut byte = [0u8; 1];
    while !head.windows(4).any(|w| w == b"\r\n\r\n") {
        if head.len() >= MAX_HEAD {
            client.write_all(BAD).await?;
            return Ok(());
        }
        let n = match tokio::time::timeout(IO_TIMEOUT, client.read(&mut byte)).await {
            Ok(Ok(n)) => n,
            Ok(Err(e)) => return Err(e),
            Err(_) => {
                let _ = client.write_all(BAD).await;
                return Ok(());
            }
        };
        if n == 0 {
            return Ok(());
        }
        head.push(byte[0]);
    }
    let text = String::from_utf8_lossy(&head);
    let Some(request_line) = text.lines().next() else {
        client.write_all(BAD).await?;
        return Ok(());
    };
    let mut parts = request_line.split_whitespace();
    let method = parts.next().unwrap_or("");
    let target = parts.next().unwrap_or("");

    if method.eq_ignore_ascii_case("CONNECT") {
        handle_connect(client, target, &policy).await
    } else if let Some(host) = absolute_uri_host(target) {
        if !policy.is_host_allowed(&host) {
            client.write_all(DENY).await?;
        } else {
            client
                .write_all(b"HTTP/1.1 501 Not Implemented\r\nContent-Length: 0\r\n\r\n")
                .await?;
        }
        Ok(())
    } else {
        client.write_all(BAD).await?;
        Ok(())
    }
}

async fn handle_connect(
    mut client: TcpStream,
    target: &str,
    policy: &EgressPolicy,
) -> io::Result<()> {
    let Some((host, port)) = split_host_port(target) else {
        client.write_all(BAD).await?;
        return Ok(());
    };
    if !policy.is_host_allowed(&host) {
        client.write_all(DENY).await?;
        return Ok(());
    }
    let addrs: Vec<SocketAddr> = match tokio::time::timeout(
        IO_TIMEOUT,
        tokio::net::lookup_host((host.as_str(), port)),
    )
    .await
    {
        Ok(Ok(it)) => it.filter(|a| policy.is_ip_allowed(a.ip())).collect(),
        Ok(Err(_)) | Err(_) => {
            client.write_all(DENY).await?;
            return Ok(());
        }
    };
    if addrs.is_empty() {
        client.write_all(DENY).await?;
        return Ok(());
    }
    let mut upstream_opt: Option<TcpStream> = None;
    for addr in addrs {
        match TcpStream::connect(addr).await {
            Ok(s) => {
                upstream_opt = Some(s);
                break;
            }
            Err(_) => continue,
        }
    }
    let mut upstream = match upstream_opt {
        Some(s) => s,
        None => {
            client
                .write_all(b"HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\n\r\n")
                .await?;
            return Ok(());
        }
    };
    client.write_all(OK).await?;
    let _ = tokio::io::copy_bidirectional(&mut client, &mut upstream).await;
    Ok(())
}

fn split_host_port(s: &str) -> Option<(String, u16)> {
    let (host, port) = s.rsplit_once(':')?;
    let port: u16 = port.parse().ok()?;
    let host = host
        .trim_start_matches('[')
        .trim_end_matches(']')
        .to_string();
    if host.is_empty() {
        None
    } else {
        Some((host, port))
    }
}

fn absolute_uri_host(target: &str) -> Option<String> {
    let rest = target
        .strip_prefix("http://")
        .or_else(|| target.strip_prefix("https://"))?;
    let authority = rest.split('/').next().unwrap_or(rest);
    let host = authority
        .rsplit_once(':')
        .map(|(h, _)| h)
        .unwrap_or(authority);
    let host = host.trim_start_matches('[').trim_end_matches(']');
    (!host.is_empty()).then(|| host.to_string())
}

// ============== main (from examples/egress_proxy.rs) ==============

#[tokio::main]
async fn main() -> io::Result<()> {
    let bind = std::env::var("EGRESS_BIND").unwrap_or_else(|_| "127.0.0.1:8443".into());
    let allow: Vec<String> = std::env::var("EGRESS_ALLOW")
        .unwrap_or_default()
        .split(',')
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .collect();
    let policy = if allow.is_empty() {
        EgressPolicy::deny_all()
    } else {
        EgressPolicy::deny_all().allow_domains(allow)
    };
    let listener = TcpListener::bind(&bind).await?;
    eprintln!("egress proxy listening on {bind} (allow={allow:?})");
    EgressProxy::new(policy).serve(listener).await
}

